   "id": "z0c46a6c6",
   "sez": "mondo",
   "titolo": "La Cina valuterebbe l'ipotesi di ospitare un vertice tra Xi, Trump e Putin",
   "orig": "Beijing faces its Russia dilemma amid talk of Xi-Trump-Putin summit",
   "lead": "Il governo della Repubblica Popolare Cinese sta valutando attentamente i rischi diplomatici legati alla possibilità di organizzare un vertice a tre tra il presidente Xi Jinping, il leader russo Vladimir Putin e il presidente statunitense Donald Trump. L'incontro ai massimi livelli offrirebbe un'indubbia visibilità mediatica favorevole al Cremlino, ma rischierebbe di compromettere la reputazione globale di Pechino, costringendo la diplomazia cinese a muoversi con estrema cautela nello scenario internazionale. Lo riferisce Deutsche Welle.",
   "more": [
    "I vertici multilaterali tra le superpotenze globali richiedono complessi negoziati preparatori per definire l'agenda politica ed evitare ricadute d'immagine negative. La posizione della Cina rimane delicata a causa del suo ruolo economico globale e del desiderio di mantenere relazioni stabili sia con l'Occidente sia con la Russia."
   ],
