   "id": "z8b7e7cbb",
   "sez": "sport",
   "titolo": "Mauricio Pochettino lascia la nazionale USA e diventa allenatore del Manchester United",
   "orig": "Manchester United names USMNT coach Mauricio Pochettino as its manager",
   "lead": "L'allenatore argentino Mauricio Pochettino ha concluso il proprio incarico alla guida della nazionale maschile di calcio degli Stati Uniti per assumere la guida tecnica del Manchester United. Durante la sua gestione, il commissario tecnico aveva condotto la selezione statunitense fino agli ottavi di finale dei Campionati Mondiali dello scorso anno. Il tecnico lascia la panchina della squadra americana per fare ritorno nel calcio di club e dirigere la formazione inglese nel campionato di Premier League. Lo riferisce NPR.",
   "more": [
    "La guida tecnica di un club di rilievo globale come il Manchester United comporta notevoli pressioni sui risultati sportivi nel campionato inglese e nelle coppe europee. Il passaggio dalla gestione di una selezione nazionale a quella quotidiana di una squadra richiede un adattamento repentino ai ritmi serrati della stagione."
   ],
