   "id": "ze36ca3c8",
   "sez": "prima",
   "titolo": "Papa Leone XIV in visita in Perù per una storica tappa pastorale",
   "orig": "El papa León XIV vuelve a Perú y pide ante sus autoridades honestidad",
   "lead": "Papa Leone XIV è giunto in Perù per iniziare una solenne visita pastorale nel Paese in cui ha svolto oltre vent'anni di servizio religioso. Ad accoglierlo a Lima e nelle successive tappe vi sono state folle imponenti di fedeli, stimate in circa tre milioni di persone lungo le strade. A Chiclayo il Pontefice ha presieduto una messa campale nelle Pampas de Pimentel davanti a centinaia di migliaia di partecipanti, chiedendo trasparenza e onestà ai governanti e visitando i luoghi storici della sua precedente attività diocesana.",
   "more": [
    "Il Perù vanta una profonda tradizione cattolica che risale all'epoca coloniale. La presenza di un pontefice che vi ha risieduto a lungo e ne conosce il tessuto sociale rende il viaggio pastorale un momento di grande rilevanza spirituale, culturale ed ecclesiastico per l'intera nazione andina."
   ],
