   "id": "z9f430be0",
   "sez": "prima",
   "titolo": "Scotland Yard indaga su David Walliams per presunti reati sessuali",
   "orig": "Police investigating David Walliams over reports alleging serious sexual offences",
   "lead": "La Metropolitan Police di Londra ha avviato un'indagine formale nei confronti del comico e celebre autore di libri per bambini David Walliams per presunti gravi reati di natura sessuale. Gli investigatori britannici hanno precisato che le accuse al vaglio sono distinte da quelle diffuse precedentemente dagli emittenti e quotidiani locali. Secondo le indiscrezioni pubblicate dai media, lo scrittore avrebbe sfruttato la propria notorietà per addebitare comportamenti illeciti verso ragazze e giovani donne, innescando accertamenti approfonditi da parte delle forze dell'ordine.",
   "more": [
    "Le indagini preliminari condotte dalla polizia britannica servono ad accertare la veridicità delle denunce raccolte prima dell'eventuale formulazione di capi d'imputazione ufficiali. La legislazione locale garantisce il rispetto del principio di presunzione d'innocenza fino all'eventuale conclusione dell'iter giudiziario nei vari gradi di giudizio."
   ],
