   "id": "z3cdf601f",
   "sez": "prima",
   "titolo": "Nvidia valuta il CEO di Arm Rene Haas per la successione al vertice",
   "orig": "Nvidia approached Arm CEO Haas to succeed Huang, FT reports",
   "lead": "Il consiglio di amministrazione del colosso dei microchip Nvidia ha contattato Rene Haas, amministratore delegato del produttore britannico di semiconduttori Arm Holdings, per valutare la sua candidatura alla guida dell'azienda. La ricerca di un nuovo vertice si è resa necessaria dopo le improvvise dimissioni di Jensen Huang. La decisione della dirigenza punta a individuare una figura di alto profilo tecnologico nel settore dei semiconduttori per assicurare la continuità strategica della società leader nelle tecnologie per l'intelligenza artificiale.",
   "more": [
    "Nvidia e Arm Holdings sono aziende chiave nell'architettura dei chip per l'informatica moderna e i centri dati. Il cambio della leadership al vertice di una compagnia da cui dipendono le infrastrutture globali d'intelligenza artificiale suscita grande attenzione da parte dei mercati finanziari e dei governi internazionali."
   ],
