   "id": "z975c604f",
   "sez": "mondo",
   "titolo": "Le vendite degli Stati Uniti a Cuba superano quelle della Cina",
   "orig": "EE UU duplica las ventas de China a Cuba, pero Pekín sigue siendo el primer socio de La Habana",
   "lead": "I dati commerciali indicano che le esportazioni degli Stati Uniti verso Cuba hanno superato un miliardo di dollari nei primi nove mesi dell'anno, raddoppiando il volume delle vendite effettuate dalla Cina nel medesimo periodo, pari a circa 523 milioni di dollari. Nonostante la forte crescita dell'interscambio con i fornitori americani, Pechino mantiene comunque la qualifica di principale partner economico strategico di L'Avana. La variazione nei flussi evidenzia le dinamiche complesse che caratterizzano il rifornimento di beni essenziali sull'isola caribica.",
   "more": [
    "Il commercio tra gli Stati Uniti e Cuba è regolato da specifiche deroghe normative all'embargo economico, che consentono la vendita di prodotti agricoli e beni alimentari di prima necessità con pagamento anticipato. Questo canale di fornitura garantisce una vicinanza geografica ed economica fondamentale per l'approvvigionamento dell'isola."
   ],
