   "id": "zacb2b3dc",
   "sez": "salute",
   "titolo": "Le cellule iPS aprono nuove prospettive per la cura delle malattie rare",
   "orig": "The iPS Cell Breakthroughs Reshaping Drug Discovery for Rare Disease",
   "lead": "La ricerca medica in Giappone sta ottenendo risultati promettenti nell'impiego delle cellule staminali riprogrammate iPS per la scoperta di farmaci destinati alle malattie rare. Le équipe di studiosi, guidate dal professor Okano Hideyuki dell'Università Keiō, stanno ricostruendo i modelli patologici in laboratorio per testare direttamente sui tessuti umani l'efficacia delle molecole candidate. L'avvio dell'applicazione clinica per le lesioni del midollo spinale segna l'ingresso della tecnologia nella fase di sperimentazione pratica sui pazienti.",
   "more": [
    "Le cellule staminali pluripotenti indotte (iPS) vengono ottenute riprogrammando cellule adulte al fine di farle differenziare in vari tipi di tessuto. La tecnologia permette di studiare l'evoluzione delle malattie rare direttamente in provetta e di abbreviare i tempi di sperimentazione di nuove terapie farmacologiche."
   ],
