   "sez": "mondo",
   "titolo": "Scott Colom eletto senatore del Mississippi negli Stati Uniti",
   "orig": "Before Scott Colom, these two men were the last black US senators from Mississippi",
   "lead": "Il candidato del Partito Democratico Scott Colom ha ottenuto la vittoria alle elezioni per il Senato degli Stati Uniti nello Stato del Mississippi. Si tratta di un risultato storico per lo Stato del sud conservatore, che non eleggeva un senatore di colore dal XIX secolo. La campagna elettorale del neosenatore è stata caratterizzata da un'elevata affluenza alle urne e da una vasta diffusione di messaggi promozionali che hanno permesso l'affermazione democratica in un collegio tradizionalmente favorevole ai repubblicani.",
   "more": [
    "Il Senato degli Stati Uniti è composto da cento membri, due per ogni Stato della nazione. La rappresentanza politica negli Stati del Sud ha visto una complessa evoluzione storica dalla fine dell'epoca della Ricostruzione, rendendo l'elezione di senatori afroamericani un evento di notevole rilievo simbolico e politico."
   ],
