   "sez": "organizzazioni",
   "titolo": "Il presidente António Costa illustra gli esiti del vertice informale dell'UE",
   "orig": "Remarks by President António Costa at the press conference following the informal meeting of Heads of State or Government of 13 November 2026",
   "lead": "Al termine della riunione informale dei Capi di Stato o di Governo tenutasi il 13 novembre 2026, il presidente del Consiglio europeo António Costa ha tenuto una conferenza stampa a Bruxelles per illustrare le conclusioni dei lavori. Durante il suo intervento davanti ai giornalisti, Costa ha presentato i principali punti di intesa raggiunti dai leader europei, incentrati sugli sviluppi delle tecnologie di intelligenza artificiale e sul prosieguo delle iniziative di supporto e cooperazione nei confronti dell'Ucraina. Lo riferisce Consiglio dell'Unione europea.",
   "more": [
    "Il Consiglio europeo riunisce i vertici di Stato e di governo dei Paesi membri per definire gli orientamenti politici generali dell'Unione Europea. Le riunioni informali offrono un contesto di confronto strategico su sfide globali prioritarie come l'innovazione digitale e la politica estera comunitaria."
   ],
