   "id": "z2290908c",
   "sez": "dibattito",
   "titolo": "L'inflazione ricalcola l'IRPEF: il fenomeno del fiscal drag sul ceto medio",
   "orig": "Anche quest’anno l’inflazione ci farà pagare più tasse",
   "lead": "In Italia si discute degli effetti dell'inflazione sul carico fiscale dei cittadini in vista dell'attuazione della manovra finanziaria. Secondo i calcoli forniti dall'Istat, il ritorno del fenomeno noto come fiscal drag rischia di annullare i benefici economici delle misure inserite nella legge di bilancio a sostegno dei redditi. Il meccanismo spinge i contribuenti in aliquote d'imposta più elevate a causa dell'adeguamento dei salari all'aumento del costo della vita, traducendosi in un maggior prelievo fiscale. Lo riferisce Il Post.",
   "more": [
    "Il drenaggio fiscale si verifica quando l'inflazione fa salire i salari nominali senza che aumenti il potere d'acquisto reale dei lavoratori. In presenza di un'imposta progressiva sul reddito a scaglioni come l'IRPEF, l'aumento del reddito nominale fa scattare l'applicazione di aliquote percentuali superiori. Ciò comporta un prelievo fiscale proporzionalmente maggiore se gli scaglioni d'imposta non vengono adeguati all'andamento dell'inflazione, riducendo l'efficacia dei bonus statali."
   ],
   "fonti": [
    {
     "n": "Il Post",
     "p": "IT",
     "c": "Milano",
     "u": "https://www.ilpost.it/2026/11/13/tasse-fiscal-drag-istat-irpef-legge-di-bilancio-2027/",
     "angolo": "",
     "atlas": "Italy",
     "t": "2026-11-13T16:55+00:00"
    }
   ],
   "data": "13 nov",
   "ora": "20:12",
   "uscita": "sera"
