   "titolo": "Un cantiere nello Stato di New York sospeso per rischi di crollo dello scavo",
   "orig": "Engineer Warned Deep Excavation Required Design Before NY Project Was Shut Down",
   "lead": "Gli ispettori federali della sicurezza sul lavoro hanno individuato alcuni operai impiegati accanto a un terrapieno instabile presso uno scavo profondo circa 23 metri a Monroe, nello Stato di New York. La situazione di pericolo nel cantiere destinato a un progetto a uso misto ha spinto le autorità comunali a ordinare l'immediata chiusura del sito. L'intervento è giunto dopo che un ingegnere aveva già espresso avvertimenti sulla necessità di una progettazione specifica. Lo riferisce Engineering News-Record.",
   "more": [
    "Negli scavi di notevole profondità la stabilità delle pareti è un fattore critico per prevenire smottamenti improvvisi. Le normative sulla sicurezza nei cantieri impongono calcoli geotecnici accurati e la posa di strutture di contenimento per proteggere le maestranze da possibili crolli di terreno durante le fasi lavorative."
   ],
