   "id": "zd8aa3c5e",
   "sez": "adolescenti",
   "titolo": "La linea del Ministero dell'Istruzione sull'uso dell'intelligenza artificiale a scuola",
   "orig": "IA a scuola, Frassinetti: “Strumento di potenziamento, ma non sostituirà mai il docente. Bisogna educare alla consapevolezza” (VIDEO)",
   "lead": "Il Ministero dell'Istruzione e del Merito ha definito la linea strategica per l'introduzione dell'intelligenza artificiale nelle aule italiane, puntando sulla formazione dei docenti e su nuovi investimenti nelle infrastrutture digitali. Come affermato dal sottosegretario Paola Frassinetti, la nuova tecnologia deve rappresentare uno strumento di potenziamento didattico senza mai sostituire la figura dell'insegnante, mantenendo al centro la centralità della persona ed educando gli studenti a un utilizzo consapevole. Lo riferisce Orizzonte Scuola.",
   "more": [
    "L'adozione di strumenti digitali avanzati nelle scuole intende ammodernare la didattica e preparare gli studenti alle sfide tecnologiche future. Allo stesso tempo, le istituzioni sottolineano l'importanza di affiancare alla tecnologia principi etici condivisi, garantendo che gli algoritmi non pregiudichino la relazione educativa tra docenti ed studenti."
   ],
