   "orig": "Queens of the Stone Age try something new on 'Perfecth'",
   "lead": "La rock band statunitense Queens of the Stone Age ha intrapreso nuove direzioni musicali all'interno del suo nono album in studio, intitolato \"Perfecth\". Per accompagnare il lancio dell'opera, il gruppo ha pubblicato il video del singolo \"From The Cliff\", co-scritto dal frontman Josh Homme, che appare direttamente nel filmato promozionale basato su uno stile visivo crudo e d'impatto.",
