    "Fondati negli anni Novanta, i Queens of the Stone Age rappresentano uno dei gruppi di maggior successo del rock alternativo globale. La ricerca di sonorità inedite conferma la volontà della band di rinnovare il proprio stile artistico pur mantenendo una forte identità stilistica nel panorama discografico."
