   "titolo": "Barbados cade contro Guadalupa e deve vincere per la qualificazione in Gold Cup",
   "orig": "Barbados must defeat Saint Lucia to seal Gold Cup qualification",
   "lead": "La nazionale di calcio di Barbados ha subito la prima sconfitta nel Gruppo B della Lega B di Concacaf Nations League, venendo superata per 3-0 dai padroni di casa della Guadalupa allo Stade Roger Zami. A seguito di questo risultato, la formazione barbadiana dovrà obbligatoriamente sconfiggere Saint Lucia nel prossimo incontro per garantirsi il passaggio del turno e conquistare la qualificazione alla Gold Cup. Lo riferisce Barbados Today.",
   "more": [
    "La Concacaf Nations League è la competizione calcistica riservata alle squadre nazionali dell'America del Nord, dell'America Centrale e dei Caraibi. Oltre all'assegnazione del titolo continentale, la fase a gironi determina l'accesso diretto alla Gold Cup, il torneo più prestigioso della confederazione."
   ],
