   "sez": "mondo",
   "titolo": "L'AfD candida l'ex calciatore Thomas Berthold alla presidenza in Germania",
   "orig": "Germania, l’Afd candida alla presidenza l’ex calciatore tedesco Berthold: giocò con Roma e Verona",
   "lead": "Il partito di estrema destra tedesco Alternative für Deutschland ha scelto di candidare alla presidenza della Germania l'ex calciatore Thomas Berthold, campione del mondo con la nazionale nel 1990 e noto per aver militato in Italia con le maglie di Roma e Verona. Berthold, noto anche per le sue posizioni contrarie ai vaccini e vicino a contesti complottisti anti-restrizioni, non ha possibilità concrete di vittoria nell'elezione presidenziale.",
   "more": [
    "La figura del Presidente della Repubblica Federale Tedesca ha un ruolo prevalentemente rappresentativo e viene eletta dall'Assemblea Federale, composta dai membri del Bundestag e da delegati dei Paesi membri. Le candidature presentate dalle forze politiche minoritarie servono spesso ad affermare posizioni ideologiche o a dare visibilità mediatica al partito."
   ],
