   "id": "ze5950f2d",
   "sez": "ambiente",
   "titolo": "I dieci anni dal terremoto di Kaikōura vissuti a Woodchester Station",
   "orig": "Country Life: Woodchester Station 10 years after the Kaikōura quake",
   "lead": "A dieci anni di distanza dal violento terremoto che ha colpito la regione di Kaikōura, la famiglia Kelly ha tracciato un bilancio delle conseguenze subite presso la tenuta agricola di Woodchester Station. I proprietari hanno ripercorso i momenti dell'evento sismico che ha sconvolto la loro vita quotidiana e analizzato i progressi compiuti nel percorso di ricostruzione e ripresa delle attività svolto durante l'ultimo decennio. Lo riferisce RNZ.",
   "more": [
    "I grandi eventi sismici provocano alterazioni profonde sia sul piano sociale sia su quello idrogeologico e strutturale delle aree rurali. La ricostruzione a lungo termine richiede interventi complessi per ripristinare le infrastrutture danneggiate, stabilizzare i terreni e garantire la sostenibilità economica delle imprese agricole coinvolte."
   ],
