   "id": "z88b91ec5",
   "sez": "ingegneria",
   "titolo": "Ferrovial si aggiudica un progetto idrico da 538 milioni di dollari in Texas",
   "orig": "Ferrovial wins $538M Texas water project",
   "lead": "La multinazionale delle infrastrutture Ferrovial si è aggiudicata un contratto da 538 milioni di dollari per realizzare un impianto idrico a Fort Worth, in Texas. Le opere di bonifica e riciclo delle acque saranno eseguite tramite la controllata Webber e costituiscono la più grande opera infrastrutturale nel settore idrico mai ottenuta dal gruppo spagnolo negli Stati Uniti d'America. Lo riferisce Construction Dive.",
   "more": [
    "Gli interventi sulle infrastrutture idriche negli Stati Uniti rispondono alla crescente domanda di gestione sostenibile delle risorse idriche e di ammodernamento degli impianti urbani. L'impiego di tecnologie avanzate per il recupero delle acque consente di ridurre lo spreco idrico e soddisfare il fabbisogno delle aree metropolitane in rapida espansione."
   ],
