   "id": "z65e47bbc",
   "sez": "cultura",
   "titolo": "Asghar Farhadi torna al cinema con il film Storie Parallele",
   "orig": "“Quanto possiamo fidarci di ciò che ci viene presentato come verità?”, Asghar Farhadi torna al cinema con Storie Parallele",
   "lead": "Il regista iraniano Asghar Farhadi, vincitore di due premi Oscar, torna nei cinema con la pellicola intitolata \"Storie Parallele\", a cinque anni di distanza dal suo ultimo lungometraggio \"Un eroe\". L'opera affronta il tema dell'affidabilità delle informazioni e della verità nell'epoca contemporanea, interrogandosi su quanto la realtà percepita dal pubblico sia autentica oppure filtrata e manipolata prima di essere fruita dagli individui. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Il cinema di Asghar Farhadi si distingue per l'esplorazione delle dinamiche morali, familiari e sociali della società moderna. Attraverso narrazioni realistiche e complesse, l'autore iraniano analizza i confini etici della verità e le conseguenze delle incomprensioni umane nelle relazioni quotidiane."
   ],
