   "id": "z9101993b",
   "sez": "tech",
   "titolo": "I ritardi della tecnologia di difesa americana creano difficoltà in Europa",
   "orig": "Does Europe regret its bet on U.S. defense?",
   "lead": "I paesi europei stanno affrontando le conseguenze degli ingenti investimenti effettuati nella tecnologia di difesa statunitense, a causa dei lunghi ritardi nelle consegne accumulati dalle industrie americane. Le lentezze nella produzione, unite alle priorità di riarmo delle stesse forze armate statunitensi, hanno generato accumuli negli ordini europei, mettendo in discussione la dipendenza tecnologica dell'Europa dagli apparati militari di Washington. Lo riferisce NPR.",
   "more": [
    "La dipendenza dell'Europa dalle forniture militari statunitensi è un tema centrale nel dibattito sulla difesa comune europea. L'impossibilità di ricevere celermente i sistemi d'arma ordinati spinge i governi dell'Unione ad accelerare lo sviluppo di un'industria bellica continentale autonoma."
   ],
