   "id": "z31528156",
   "sez": "spazio",
   "titolo": "Robot ispirati alle lumache per l'esplorazione dei pianeti extra-terrestri",
   "orig": "Shape-Shifting Robotic \"Slugs\" Could One Day Crawl Across Alien Worlds",
   "lead": "I ricercatori dell'Adaptive Robotics Lab della Colorado State University hanno sviluppato il prototipo di un robot con morfologia variabile, simile a una lumaca, destinato all'esplorazione di mondi alieni. A differenza dei veicoli dotati di ruote o pale, inadatti ad affrontare rocce appuntite o fenditure strette, la nuova struttura robotica permette ai dispositivi di strisciare su terreni impervi e irregolari durante le missioni spaziali. Lo riferisce Universe Today.",
   "more": [
    "L'esplorazione robotica dei corpi celesti richiede soluzioni ingegneristiche in grado di superare la rigidità dei tradizionali rover. La robotica morbida e le strutture a forma variabile permettono ai moduli esplorativi di adattare la propria conformazione al suolo, riducendo il rischio di incastramento in canyon o zone rocciose."
   ],
