   "id": "z81d0c64c",
   "sez": "italia",
   "titolo": "Polemiche in Azione dopo l'uscita di D'Amato e la replica di Calenda",
   "orig": "Calenda: “D’Amato aveva un accordo con il dem Mancini per fare l’assessore. Io non mi candido a Roma”",
   "lead": "Il leader di Azione Carlo Calenda è intervenuto dopo la fuoriuscita dal partito di Alessio D'Amato, sostenendo che l'ex consigliere avesse stretto un accordo con il democratico Mancini per ottenere un incarico da assessore. Calenda ha criticato la scelta dell'esponente politico di non informare la dirigenza, ribadendo che il partito non virerà a destra e smentendo una propria candidatura a sindaco di Roma, dopo aver già avuto un colloquio con il sindaco Roberto Gualtieri. Lo riferisce la Repubblica.",
   "more": [
    "Gli equilibri politici all'interno dei partiti centristi italiani sono spesso caratterizzati da confronti sulla collocazione e le alleanze a livello locale e nazionale. Le dinamiche elettorali nelle grandi città come Roma influenzano direttamente la stabilità delle coalizioni di centro-sinistra e centro-destra."
   ],
