   "titolo": "Theon Design festeggia dieci anni di modifiche della Porsche 911",
   "orig": "Theon Design celebrates ten years of transforming the classic air-cooled Porsche 911",
   "lead": "L'officina britannica Theon Design festeggia dieci anni di attività nel settore dei restomod dedicati alla classica Porsche 911 raffreddata ad aria. Lo specialista del Regno Unito ha celebrato il traguardo presentando una serie di interventi migliorativi, sia sottili sia più evidenti, volti ad ammodernare le prestazioni e l'estetica dell'iconica vettura sportiva senza alterarne l'architettura originale. Lo riferisce Wallpaper*.",
   "more": [
    "Il restomod è una pratica automobilistica che unisce il restauro di vetture d'epoca all'installazione di componenti meccaniche e tecnologiche moderne. Questo approccio consente di mantenere il fascino estetico dei veicoli storici garantendo al contempo standard di sicurezza, affidabilità e prestazioni paragonabili alle auto contemporanee."
   ],
