   "titolo": "Annunciata la partecipazione di Black onyX all'evento per Cosmic Princess Kaguya",
   "orig": "Cosmic Princess Kaguya! Virtual Event Announces Guest Performers Black onyX",
   "lead": "L'evento virtuale Tsukuyomi Kansha-sai, dedicato all'opera Cosmic Princess Kaguya, vedrà la partecipazione del gruppo musicale Black onyX come ospiti speciali. La manifestazione si terrà il prossimo 26 dicembre e sarà trasmessa in diretta sulle piattaforme YouTube e VRChat, offrendo agli appassionati esibizioni dal vivo ed esperienze immersive nel mondo virtuale. Lo riferisce Crunchyroll News.",
   "more": [
    "Gli eventi all'interno di ambienti di realtà virtuale come VRChat rappresentano una modalità di intrattenimento sempre più diffusa nella cultura pop giapponese. Queste piattaforme consentono agli spettatori di interagire tramite avatar e assistere a concerti di artisti virtuali o reali in spazi digitali altamente personalizzati."
   ],
