   "sez": "economia",
   "titolo": "Scontro sui posti di lavoro nelle acciaierie canadesi dopo i dazi di Trump",
   "orig": "The fight over Canadian steelworker jobs",
   "lead": "Negli stabilimenti siderurgici canadesi si è acceso un dibattito sulla salvaguardia dei posti di lavoro presso la Stelco, a seguito dei licenziamenti attribuiti dal proprietario statunitense all'introduzione dei dazi commerciali promossi da Donald Trump. Tuttavia, il sostegno espresso dallo stesso gruppo industriale a favore delle tariffe protezionistiche ha sollevato forti polemiche tra i lavoratori e i rappresentanti del settore industriale locale. Lo riferisce Al Jazeera.",
   "more": [
    "Le barriere doganali sull'acciaio e sull'alluminio influenzano direttamente le catene produttive integrate tra Stati Uniti e Canada. Sebbene i dazi mirino a proteggere la produzione interna, essi provocano spesso ritorsioni commerciali, aumento dei costi dei materiali e riduzioni dell'occupazione nelle industrie esportatrici dei Paesi partner."
   ],
