   "id": "zc140599e",
   "sez": "spazio",
   "titolo": "Gli ammassi di galassie densi rallentano la formazione delle stelle",
   "orig": "Dense Galaxy Clusters Foster Mechanisms That Throttle Star Formation",
   "lead": "Una nuova ricerca scientifica condotta sugli ammassi di galassie particolarmente densi ha individuato i meccanismi cosmici che limitano la nascita di nuove stelle nell'universo. Sebbene durante l'epoca del cosiddetto \"Mezzogiorno Cosmico\" la formazione stellare fosse estremamente intensa, il fenomeno si è successivamente ridotto in modo significativo, fornendo indizi fondamentali sulla trasformazione e sul consumo dell'idrogeno gassoso necessario alla creazione degli astri. Lo riferisce Universe Today.",
   "more": [
    "La formazione stellare richiede grandi quantità di idrogeno gassoso freddo, il quale collassa sotto l'azione della propria gravità. All'interno degli ammassi galattici densi, le elevate temperature del mezzo intergalattico e le interazioni gravitazionali possono riscaldare o disperdere il gas, impedendogli di condensarsi in nuove stelle."
   ],
