   "sez": "sport",
   "titolo": "La nazionale femminile portoghese sfida l'Inghilterra in Nations League",
   "orig": "Seleção feminina de futebol abre Liga das Nações com bicampeã europeia Inglaterra",
   "lead": "La nazionale femminile di calcio del Portogallo farà il suo esordio nella nuova edizione della Women's Nations League affrontando in casa l'Inghilterra, squadra due volte campionessa d'Europa. La partita, inserita nel Gruppo 2 della Lega A del torneo continentale, è stata ufficializzata dalla Federazione Calcistica Portoghese come primo impegno casalingo per le atlete lusitane nella competizione. Lo riferisce RTP.",
   "more": [
    "La UEFA Women's Nations League è la struttura competitiva riservata alle selezioni nazionali femminili europee, suddivisa in leghe in base al merito sportivo. Il torneo determina sia l'assegnazione del trofeo continentale sia gli accessi ai principali campionati mondiali e olimpici."
   ],
