   "id": "z51ea5eab",
   "sez": "musica",
   "titolo": "Concerto di anteprima a Lemba per il festival di musica jazz e mondiale di Cipro",
   "orig": "Curtain raiser for jazz festival coming to Lemba",
   "lead": "A Lemba, a Cipro, si terrà un evento musicale di anteprima in vista del tredicesimo Cyprus Jazz & World Music Showcase, in programma al Rialto Theatre dal quattro al sei dicembre. L'iniziativa è organizzata dal dipartimento della cultura contemporanea in collaborazione con il teatro di Limassol e si svolgerà presso il Lemba Cultural Village. Durante la serata si esibirà il gruppo Soulful Groove Collective, una formazione che aveva già partecipato con successo all'edizione dello scorso anno della manifestazione. L'evento intende promuovere la musica dal vivo e introdurre il pubblico all'imminente rassegna cipriota. Lo riferisce Cyprus Mail.",
   "more": [
    "I festival dedicati alla musica jazz e World Music rappresentano una piattaforma di rilievo per valorizzare artisti locali e internazionali, favorendo lo scambio culturale e la promozione delle arti visive e sonore. Attraverso eventi di anteprima nei centri culturali minori, le istituzioni cipriote mirano a coinvolgere un pubblico più ampio e a consolidare la scena artistica del territorio."
   ],
