   "sez": "tech",
   "titolo": "Attacco informatico contro un produttore tedesco di droni destinati all'Ucraina",
   "orig": "Cyberattack hits German drone manufacturer supplying Ukraine in late October, company confirms",
   "lead": "In Germania un'azienda specializzata nella produzione di droni per le forze armate ucraine è stata colpita da un grave attacco informatico avvenuto alla fine di ottobre. La conferma dell'intrusione è giunta direttamente dall'impresa attraverso un comunicato ufficiale. La società ha spiegato che le realtà produttive impegnate nel sostegno militare all'Ucraina rappresentano un bersaglio primario per gli hacker proprio per la rilevanza strategica della loro attività nella sicurezza dei clienti. Le incursioni digitali mirano a sabotare la catena di fornitura o a sottrarre informazioni riservate sulla tecnologia dei velivoli senza pilota forniti a Kyiv. Lo riferisce The Kyiv Independent.",
   "more": [
    "La guerra ciberstatale e il cybersabotaggio costituiscono una componente rilevante dei moderni conflitti asimmetrici. Le aziende del settore della difesa che producono droni e sistemi tecnologici avanzati rappresentano bersagli primari per attacchi informatici volti a compromettere dati sensibili, interrompere la produzione o rilevare dettagli tecnici sulle forniture militari in corso."
   ],
