   "id": "zd3db2d74",
   "sez": "tech",
   "titolo": "Polonia, il presidente Nawrocki pone il veto alla legge di controllo dei contenuti online",
   "orig": "Președintele Poloniei a blocat legea care permitea autorităților să cenzureze conținutul ilegal de pe internet",
   "lead": "A Varsavia il presidente della Polonia Karol Nawrocki ha respinto tramite veto un progetto di legge che avrebbe concesso all'autorità di regolamentazione la facoltà di stabilire l'illegalità dei contenuti e dei post pubblicati su internet. È la seconda volta che il capo dello Stato si oppone alla normativa nazionale concepita per attuare le disposizioni previste dal regolamento europeo sui servizi digitali, noto come Digital Services Act. Il presidente ha motivato la propria scelta difendendo la libertà di espressione online ed esprimendo contrarietà all'assegnazione di poteri di censura diretta sugli utenti alle agenzie governative. Lo riferisce HotNews.",
   "more": [
    "Il Digital Services Act è il regolamento dell'Unione Europea destinato a contrastare la diffusione di contenuti illegali e disinformazione sulle piattaforme digitali. L'applicazione nei singoli Stati membri richiede l'adeguamento dei quadri normativi nazionali e l'individuazione di autorità di vigilanza, determinando accesi dibattiti sul bilanciamento tra la sicurezza in rete e la tutela della libertà di manifestazione del pensiero."
   ],
