   "id": "z043e28f9",
   "sez": "adolescenti",
   "titolo": "Valle d'Aosta, contributo sanitario integrativo di 120 euro all'anno per gli insegnanti",
   "orig": "Copertura sanitaria integrativa, in Valle d’Aosta agli insegnanti 120 euro. La Regione stanzia 240 mila euro annui",
   "lead": "In Valle d'Aosta gli insegnanti delle scuole regionali riceveranno un contributo economico annuale di circa 120 euro destinato alla copertura sanitaria integrativa. L'importo erogato risulta più che doppio rispetto ai 59 euro riconosciuti al personale docente del restante territorio nazionale. Per finanziare la misura di sostegno, l'amministrazione regionale ha deliberato uno stanziamento complessivo di 240 mila euro all'anno. Il provvedimento punta ad ampliare le tutele sanitarie dei docenti locali, coprendo spese sanitarie e prestazioni medico-specialistiche non garantite dal sistema sanitario pubblico, valorizzando l'autonomia finanziaria della Regione a statuto speciale. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La copertura sanitaria integrativa consiste in forme di tutela previdenziale o assistenziale che rimborsano in tutto o in parte le spese mediche sostenute dai lavoratori. In Italia le Regioni a statuto speciale dispongono di autonomie finanziarie che consentono di stanziare risorse proprie per integrare i contratti collettivi nazionali e offrire servizi welfare migliorativi ai propri dipendenti pubblici."
   ],
