   "id": "z4c28fd6b",
   "sez": "salute",
   "titolo": "Dispositivo cardiaco Watchman, dubbi dei medici e strategie commerciali di Boston Scientific",
   "orig": "STAT+: Doctors have questions about the Watchman. Boston Scientific has a sales pitch.",
   "lead": "A Boston un'inchiesta condotta dal quotidiano Boston Globe ha messo in luce i dubbi sollevati dalla comunità medica nei confronti del dispositivo per impianto cardiaco Watchman, prodotto da Boston Scientific. L'indagine giornalistica ha analizzato le strategie di marketing e le campagne promozionali adottate dall'azienda produttrice, sollevando la questione se la spinta commerciale abbia superato le reali evidenze offerte dalla ricerca scientifica e dai test clinici. I medici chiedono maggiore chiarezza sulla reale efficacia e sui possibili rischi del dispositivo impiegato nei pazienti affetti da fibrillazione atriale. Lo riferisce STAT.",
   "more": [
    "Il Watchman è un dispositivo medico impiantabile progettato per la chiusura dell'auricola sinistra del cuore nei pazienti affetti da fibrillazione atriale non valvolare. Questo intervento punta a ridurre il rischio di formazione di trombi ed ictus in soggetti che presentano controindicazioni alla terapia anticoagulante orale a lungo termine, ma richiede attente valutazioni di sicurezza."
   ],
