   "id": "z49f69819",
   "sez": "adolescenti",
   "titolo": "Reclutamento docenti, Pittoni propone il doppio canale e le graduatorie GPSR",
   "orig": "Pittoni (Lega): “L’obiettivo finale è il doppio canale di reclutamento. Servono le GPSR e meccanismi che assicurino pari dignità a tutte le graduatorie”",
   "lead": "In Italia l'ex senatore della Lega Mario Pittoni è intervenuto sul tema delle assunzioni nel settore scolastico, ribadendo la necessità di introdurre un sistema a doppio canale di reclutamento degli insegnanti. Pittoni ha spiegato che gli impegni assunti dal precedente governo con la Commissione europea nell'ambito del Pnrr non si esauriscono con le tre procedure concorsuali previste, ma impongono concorsi a cadenza annuale anche in presenza di graduatorie capienti. Il rappresentante leghista ha auspicato la creazione delle graduatorie provinciali per le supplenze con valore abilitante e l'adozione di meccanismi che garantiscano pari dignità a tutti i canali d'accesso al ruolo. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il sistema di reclutamento dei docenti in Italia è oggetto di continue riforme volte a coniugare il superamento del precariato storico con le direttive europee. Il doppio canale di assunzione prevede che una quota di cattedre sia assegnata tramite concorsi ordinari per esami e un'altra attingendo dalle graduatorie per titoli ed esperienza di servizio maturate sul campo."
   ],
