   "id": "zf73359cd",
   "sez": "sport",
   "titolo": "Il calciatore Telasco Segovia candidato al premio Humanitario del Año della MLS",
   "orig": "MLS nomina a Telasco Segovia para el premio Humanitario del Año",
   "lead": "A Caracas il giornale El Nacional ha riportato la notizia della candidatura del calciatore venezuelano Telasco Segovia al premio Humanitario del Año assegnato dalla Major League Soccer. Il riconoscimento è stato promosso a seguito dell'impegno benefico dimostrato dall'atleta in collaborazione con la sua squadra, l'Inter Miami, per sostenere le popolazioni colpite dai due violenti terremoti che hanno messo a dura prova il Venezuela nel mese di giugno. Il giocatore e la società statunitense hanno organizzato raccolte fondi e inviato aiuti umanitari nelle zone terremotate per soccorrere le famiglie sfollate. Lo riferisce El Nacional.",
   "more": [
    "Il premio Humanitario del Año della Major League Soccer riconosce i calciatori e i dirigenti del campionato nordamericano che si distinguono per iniziative benefiche e impatto sociale nel mondo. L'assegnazione punta a valorizzare la responsabilità sociale degli atleti di vertice, trasformando la notorietà sportiva in aiuti concreti per comunità colpite da calamità naturali o difficoltà economiche."
   ],
