   "id": "zc0d5ef86",
   "sez": "economia",
   "titolo": "Mercati petroliferi mondiali, l'aumento delle spedizioni nel Golfo porta l'offerta in surplus",
   "orig": "Global oil markets swing to surplus as Gulf shipments rebound",
   "lead": "A Londra il Financial Times ha analizzato la situazione dei mercati energetici mondiali, registrando un ritorno in surplus dell'offerta di petrolio a causa della ripresa del traffico delle navi cisterne nel Golfo Persico. Gli analisti dell'Agenzia Internazionale dell'Energia hanno tuttavia avvertito che occorreranno diversi mesi prima di poter ricostituire le riserve strategiche di greggio che sono state gravemente intaccate dal recente conflitto tra Stati Uniti e Iran. Le fluttuazioni dei prezzi riflettono l'incertezza sulla tenuta dei flussi commerciali marittimi e la necessità di stabilizzare le scorte globali per far fronte a nuove possibili interruzioni. Lo riferisce Financial Times.",
   "more": [
    "L'equilibrio del mercato petrolifero globale è strettamente legato alla sicurezza delle rotte marittime nel Golfo Persico, da cui transita una quota consistente della produzione mondiale. Le crisi geopolitiche e i conflitti armati nella regione causano repentine variazioni nell'offerta di greggio, intaccando le scorte strategiche di sicurezza che i paesi consumatori impiegano per mitigare gli shock dei prezzi."
   ],
