   "id": "ze6489e4f",
   "sez": "salute",
   "titolo": "Stati Uniti, drammatico aumento dei casi di sifilide congenita nei neonati dal 2012 al 2022",
   "orig": "Congenital syphilis rates soared in US newborns from 2012 to 2022",
   "lead": "A Douglas la testata Medical Xpress ha segnalato uno studio pubblicato su Clinical Infectious Diseases riguardante la diffusione della sifilide congenita negli Stati Uniti. I dati evidenziano che i tassi dell'infezione tra i neonati statunitensi sono aumentati di quasi sei volte tra il 2012 e il 2022. L'incremento del contagio riguarda tutte le fasce demografiche e i differenti livelli di reddito, registrando tuttavia gli aumenti più marcati tra le popolazioni dei nativi americani. Gli autori dello studio sollecitano interventi urgenti di prevenzione e un potenziamento dei controlli prenatali per diagnosticare tempestivamente la patologia e proteggere la salute dei nascituri. Lo riferisce Medical Xpress.",
   "more": [
    "La sifilide congenita è una grave infezione trasmessa dalla madre al bambino durante la gravidanza o il parto. Se non trattata tempestivamente con antibiotici idonei, la malattia può causare natimortalità, malformazioni ossee, ritardi nello sviluppo e danni agli organi interni. Lo screening prenatale e l'accesso alle cure rappresentano gli strumenti principali per prevenire la trasmissione verticale."
   ],
