   "id": "zf41c96a4",
   "sez": "economia",
   "titolo": "Primo incontro del comitato commerciale USA-Cina prima del vertice Trump-Xi",
   "orig": "US-China Board of Trade holds first meeting days before Trump-Xi summit",
   "lead": "Gli Stati Uniti e la Cina hanno tenuto venerdì la prima riunione formale del comitato bilaterale per il commercio (Board of Trade). L'incontro, promosso dall'Ufficio del Rappresentante per il Commercio degli Stati Uniti insieme al Dipartimento del Tesoro americano e alle controparti cinesi, si è svolto a pochi giorni dal vertice previsto a Shenzhen tra il presidente statunitense Donald Trump e il leader cinese Xi Jinping. L'amministrazione Trump ha espresso l'intenzione di proseguire il confronto strategico con Pechino. Lo riferisce South China Morning Post.",
   "more": [
    "I rapporti commerciali tra le due maggiori economie mondiali sono caratterizzati da complesse dinamiche legate a dazi, tecnologia e investimenti. La creazione di canali di dialogo e di comitati bilaterali mira a stabilizzare le relazioni economiche e a facilitare le trattative ad alto livello prima dei vertici tra i rispettivi capi di Stato."
   ],
