   "id": "zb71df879",
   "sez": "economia",
   "titolo": "Il Bitcoin scende sotto i 70.000 dollari per i timori sull'inflazione",
   "orig": "Bitcoin slides below $70,000 as inflation concerns hurt crypto",
   "lead": "Il valore del Bitcoin è sceso venerdì sotto la soglia dei 70.000 dollari per la prima volta da agosto, registrando un calo complessivo fino al 9% nell'arco di due giorni. La svalutazione della principale criptovaluta, che ha toccato un minimo di 67.628 dollari prima di risalire attorno ai 69.200 dollari a New York, è stata innescata dalle preoccupazioni su inflazione e tassi di interesse elevati. La flessione ha provocato la liquidazione di circa 1,5 miliardi di dollari in posizioni rialziste. Lo riferisce The Korea Herald.",
   "more": [
    "Le criptovalute mostrano un'elevata sensibilità alle variazioni delle prospettive macroeconomiche mondiali. Quando le aspettative sull'inflazione rimangono alte e le banche centrali mantengono tassi di interesse elevati, la liquidità sui mercati finanziari tende a ridursi, spingendo gli investitori a disimpegnarsi dagli asset ritenuti più speculativi o rischiosi."
   ],
