   "id": "zc50b6cb1",
   "sez": "economia",
   "titolo": "Crescono gli investimenti azionari del fondo pensione sudcoreano negli USA",
   "orig": "NPS&apos; US stock holdings gain as tech giants outperform",
   "lead": "Il valore delle azioni statunitensi detenute dal National Pension Service della Corea del Sud è cresciuto nel terzo trimestre, sostenuto dalle buone prestazioni dei grandi gruppi tecnologici, pur in presenza di vendite nel settore dei semiconduttori. Secondo una comunicazione trasmessa venerdì alla SEC, il fondo pensione possedeva a fine settembre 158,74 miliardi di dollari in 553 società quotate negli Stati Uniti, con un aumento di 3,66 miliardi rispetto al trimestre precedente e una quota azionaria salita dello 0,9%. Lo riferisce The Korea Herald.",
   "more": [
    "I fondi pensione sovrani e istituzionali allocano quote significative del proprio patrimonio nei mercati azionari internazionali per diversificare il rischio e garantire rendimenti nel lungo periodo. I titoli dei colossi della tecnologia rappresentano spesso una componente rilevante in tali portafogli per la loro elevata capitalizzazione."
   ],
