   "sez": "economia",
   "titolo": "Gli investimenti nelle zone economiche speciali delle Filippine battono il record del 2012",
   "orig": "Ecozone investments shatter 14-yr record",
   "lead": "Gli investimenti destinati alle zone economiche speciali delle Filippine hanno superato un primato storico che resisteva da quattordici anni, raggiungendo la cifra record di 315,5 miliardi di peso nel corso del 2026. Questo risultato eclissa il precedente massimo di 311,9 miliardi di peso stabilito nel 2012. I dati aggiornati al 10 novembre indicano la possibilità di un ulteriore incremento del totale entro il termine dell'anno grazie all'approvazione di nuovi progetti. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "Le zone economiche speciali sono aree delimitate in cui le aziende beneficiano di regimi fiscali agevolati, procedure burocratiche semplificate e infrastrutture dedicate. Tali strumenti sono utilizzati dai governi per attrarre capitali esteri, promuovere l'industrializzazione e stimolare l'occupazione e le esportazioni nazionali."
   ],
