   "titolo": "Cipro, la commissione Finanze analizza i prezzi dei carburanti per evitare cartelli",
   "orig": "‘We are making sure there are no cartels’ in fuel supply",
   "lead": "La commissione Finanze del Parlamento di Cipro ha esaminato venerdì le indagini in corso sui prezzi dei carburanti, intese a verificare l'assenza di cartelli nel settore della distribuzione. Nel corso della seduta è stata discussa la proposta di bilancio di 2,75 milioni di euro destinata alla Commissione per la Tutela della Concorrenza, analizzando le specificità geografiche cipriote che, in quanto stato insulare, favoriscono la formazione di oligopoli nel mercato energetico. Lo riferisce Cyprus Mail.",
   "more": [
    "Nei mercati insulari o di ridotte dimensioni, la limitata presenza di operatori commerciali può ostacolare la piena concorrenza, favorendo dinamiche oligopolistiche. Le autorità antitrust hanno il compito di monitorare la formazione dei prezzi e prevenire intese illecite tra aziende per proteggere i consumatori da speculazioni."
   ],
