   "id": "z9109047c",
   "sez": "mondo",
   "titolo": "Spagna, al via la campagna elettorale del 29 novembre tra lo scontro su pensioni e maggioranza",
   "orig": "Campaña elecciones 29-N y actualidad política, en directo | Sánchez pide 176 diputados progresistas en el Congreso para “llegar antes y más lejos”",
   "lead": "In Spagna si è aperta la campagna elettorale per le consultazioni politiche del 29 novembre. Il presidente del governo uscente, Pedro Sánchez, ha sollecitato la mobilitazione degli elettori per ottenere una maggioranza di 176 deputati progressisti al Congresso, mentre i sondaggi posizionano le forze di destra vicine alla quota di 190 seggi. Il governo ha inoltre approvato la procedura d'urgenza per la rivalutazione delle pensioni in base all'inflazione, prevedendo un incremento stimato tra il 3% e il 4%.",
   "more": [
    "Le consultazioni elettorali spagnole si svolgono in un clima di forte polarizzazione politica tra il blocco di sinistra guidato dai socialisti e l'alleanza potenziale tra i popolari e la destra di Vox. La sostenibilità delle pensioni e l'andamento del potere d'acquisto rappresentano temi centrali nel dibattito tra i partiti in corsa."
   ],
