   "titolo": "Russia, arrestato per frode il vice capo dell'Agenzia statale per la gioventù Denis Ashirov",
   "orig": "Russian Youth Agency Deputy Chief Arrested in Fraud Probe",
   "lead": "Il vice capo e segretario di Stato dell’Agenzia statale russa per la gioventù, Denis Ashirov, è stato tratto in arresto nell'ambito di un'ampia inchiesta giudiziaria per frode. Ashirov, che ricopriva il prestigioso incarico all'interno dell'agenzia governativa dal luglio del 2022, rischia una pena fino a dieci anni di reclusione qualora venisse condannato per le irregolarità finanziarie su larga scala contestate dalle autorità inquirenti nell'ambito delle indagini sulla gestione dei fondi pubblici. Lo riferisce Moscow Times.",
   "more": [
    "L'Agenzia statale russa per la gioventù si occupa della gestione delle politiche pubbliche giovanili e dell'organizzazione di programmi educativi e patrimoniali. Le inchieste per frode all'interno degli organi governativi comportano spesso controlli rigorosi sulla destinazione dei bilanci e sulla trasparenza delle assegnazioni pubbliche."
   ],
