   "id": "z4f638971",
   "sez": "mondo",
   "titolo": "Uganda, violenta tempesta devasta un campo di rifugiati sudanesi a Kiryandongo",
   "orig": "Storm leaves Sudanese refugee families without shelter in Uganda",
   "lead": "Una violenta tempesta si è abbattuta sull'insediamento di Kiryandongo, in Uganda, distruggendo le abitazioni e le masserizie di numerose famiglie di rifugiati provenienti dal Sudan. Le avverse condizioni meteorologiche hanno causato ingenti danni alle infrastrutture locali, lasciando seicento studenti privi delle proprie aule scolastiche e circa cinquanta famiglie senza un riparo. Il maltempo ha inoltre devastato i raccolti nei villaggi vicini, provocando rilevanti perdite per gli agricoltori della regione.",
   "more": [
    "I campi di accoglienza per i rifugiati in Africa orientale affrontano costantemente vulnerabilità legate al clima e alla precarietà delle strutture abitative. Eventi meteorologici estremi come le tempeste improvvise aggravano le condizioni di vita delle popolazioni già provate da conflitti e da difficoltà di approvvigionamento."
   ],
