   "sez": "mondo",
   "titolo": "Filippine, emesso un mandato di arresto contro Quiboloy su richiesta di estradizione degli USA",
   "orig": "Arrest warrant vs Quiboloy issued over US extradition request | The wRap",
   "lead": "Le autorità giudiziarie delle Filippine hanno ufficialmente emesso un mandato di arresto nei confronti del predicatore Apollo Quiboloy, in risposta a una formale richiesta di estradizione inoltrata dagli Stati Uniti. Il provvedimento restrittivo rappresenta un passaggio chiave nelle procedure internazionali che vedono il leader religioso al centro di indagini condotte dalla magistratura federale americana per diversi e gravi capi di imputazione a suo carico negli USA. Lo riferisce Rappler.",
   "more": [
    "Le richieste di estradizione tra stati richiedono un vaglio approfondito della magistratura locale per verificare la conformità ai trattati bilaterali vigenti. Il processo valuta la sussistenza dei presupposti legali e la gravità dei reati contestati prima di autorizzare il trasferimento dell'imputato nel paese richiedente."
   ],
