   "sez": "mondo",
   "titolo": "Turchia e Qatar firmano un accordo di difesa reciproca a Istanbul",
   "orig": "Turkiye and Qatar sign mutual defence agreement",
   "lead": "Turchia e Qatar hanno siglato venerdì un accordo di difesa reciproca volto a rafforzare la cooperazione militare e strategica tra i due paesi alleati. La firma del patto è avvenuta a Istanbul al termine dell'incontro ufficiale tra il presidente turco Recep Tayyip Erdogan e l'emiro del Qatar, lo sceicco Tamim bin Hamad Al Thani, confermando l'intesa e la convergenza sulle principali questioni di sicurezza regionale.",
   "more": [
    "L'alleanza tra Turchia e Qatar si è consolidata negli anni attraverso una stretta cooperazione economica, politica e militare. La firma di un accordo di difesa reciproca rafforza il posizionamento strategico di Ankara nel Golfo e garantisce a Doha una maggiore copertura di sicurezza nel complesso scacchiere mediorientale."
   ],
