   "sez": "mondo",
   "titolo": "USA, i Democratici valutano l'impeachment di Robert F. Kennedy Jr. ma cercano i suoi elettori",
   "orig": "Democrats are weighing impeachment of RFK Jr. while courting his supporters",
   "lead": "I Democratici statunitensi valutano la possibilità di avviare una procedura di impeachment nei confronti del Segretario alla Salute Robert F. Kennedy Jr. quando insedieranno la nuova maggioranza al Congresso in gennaio. L'operato del segretario, contestato per la revisione delle linee guida sui vaccini e i tagli alla ricerca medica, ha sollevato forti critiche, anche se alcuni settori del partito cercano contemporaneamente un dialogo con i suoi sostenitori su temi condivisi come i pesticidi e la mensa scolastica.",
   "more": [
    "L'impeachment negli Stati Uniti è uno strumento d'accusa costituzionale utilizzato dal Congresso nei confronti di alti funzionari federali per gravi inadempienze o violazioni. L'avvio della procedura riflette lo scontro politico e istituzionale sulle nomine dell'amministrazione e sugli orientamenti delle politiche sanitarie nazionali."
   ],
