   "sez": "mondo",
   "titolo": "Corea del Sud, il trasferimento dell'OPCON visto da Trump come via per il ritiro delle truppe USA",
   "orig": "Trump sees OPCON transition as potential path to U.S. troop withdrawal from Korea: experts",
   "lead": "Il presidente statunitense Donald Trump considera il trasferimento del controllo operativo in tempo di guerra (OPCON) alle forze armate di Seul come un potenziale passaggio per giustificare il successivo ritiro delle truppe americane di stanza in Corea del Sud. Secondo le analisi espresse da esperti di sicurezza e di politica estera, il ridimensionamento della presenza militare statunitense nell'area rappresenterebbe un obiettivo strategico perseguito dall'amministrazione di Washington. Lo riferisce Yonhap.",
   "more": [
    "Il trasferimento del controllo operativo in caso di conflitto dalla guida statunitense all'esercito sudcoreano è un tema centrale nelle relazioni di difesa tra Washington e Seul. L'eventuale riduzione del contingente americano inciderebbe sulla struttura di deterrenza nei confronti della Corea del Nord e sugli equilibri strategici dell'Asia-Pacifico."
   ],
