   "titolo": "Zelensky scherza con Meloni a Dublino: \"Sei tu che non volevi vedermi\"",
   "orig": "Zelensky e la frecciata a Meloni: “Da quanto tempo…? Sei tu che non volevi vedermi”",
   "lead": "Durante un vertice a Dublino, la premier Giorgia Meloni ha fatto notare al presidente ucraino Volodymyr Zelensky che non si incontravano da tempo. Zelensky ha risposto con una battuta, ribaltando la questione e sostenendo che fosse lei a evitare l'incontro. Lo scambio, pubblicato dallo stesso leader ucraino su X, si è concluso con un ringraziamento all'Italia per il sostegno fornito a Kyiv. Lo riferisce ANSA.",
