   "titolo": "Frane e evacuazioni nella notte nel genovese, allerta in cinque regioni",
   "orig": "Frane nella notte ed evacuazioni in provincia di Genova",
   "lead": "Nella notte si sono verificate frane in provincia di Genova che hanno costretto alcune famiglie a evacuare le proprie case. In Toscana le ondate di piena dei fiumi, incluso l'Arno sotto osservazione speciale, sono transitate senza particolari criticità. L'allerta meteo riguarda complessivamente cinque regioni italiane, colpite da piogge intense nelle ultime ore. Lo riferiscono ANSA e Rai News, che segnalano frane anche in altre zone della Liguria.",
