   "titolo": "Cricket, Henry e Young trascinano la Nuova Zelanda: India travolta per 244 run",
   "orig": "Henry and Young shine as New Zealand thrash India by 244 runs",
   "lead": "Nella quarta partita della serie di cricket contro l'India, la Nuova Zelanda ha ottenuto una vittoria netta per 244 run, grazie alle prestazioni di Henry e Young. L'India resta avanti 2-1 nella serie di cinque incontri e si è già assicurata il successo complessivo, ma la Nuova Zelanda può ancora pareggiare il conto nella partita finale di domenica. Lo riferisce Al Jazeera.",
