   "orig": "Gérard Depardieu rinuncia all'appello nel processo per due casi di aggressione sessuale",
   "lead": "L'attore francese Gérard Depardieu ha rinunciato a presentare appello contro la sentenza di primo grado che lo ha condannato a 18 mesi di carcere per due casi di aggressione sessuale. La decisione rende di fatto definitiva la condanna emessa dal tribunale. Lo riferisce ANSA.",
