   "titolo": "Vertice Ue: entro due settimane il nome dell'inviato per l'Ucraina",
   "orig": "Summit Ue: \"Trovare inviato su Ucraina\"",
   "lead": "Al summit dell'Unione europea è emersa la necessità di individuare un inviato europeo sul dossier ucraino. Secondo quanto riferito dal rappresentante Martin, la scelta del nome avverrà entro una o due settimane. La questione si inserisce nel più ampio confronto tra Ue e Stati Uniti sulle modalità di gestione dei negoziati legati al conflitto in Ucraina. Lo riferisce Rai News.",
