   "id": "z50773254",
   "sez": "spazio",
   "titolo": "SpaceX tenta per la prima volta il recupero a terra della navicella Starship",
   "orig": "SpaceX to attempt first Starship spacecraft recovery on land in 15th flight",
   "lead": "SpaceX ha tentato, nel suo quindicesimo volo di prova, il primo recupero a terra della navicella Starship, invece di farla cadere nell'oceano come nei test precedenti. Il tentativo di \"catturare\" la navicella presso la base di lancio in Texas rappresenta un passo chiave nel progetto di Elon Musk per rendere il sistema di razzi completamente riutilizzabile. Lo riferiscono CNA e Phys.org.",
   "more": [
    "Starship è il razzo più grande e potente mai costruito, sviluppato da SpaceX per missioni verso la Luna e Marte. La riutilizzabilità completa, incluso il recupero della navicella senza perderla nell'oceano, è considerata essenziale per abbattere i costi dei lanci spaziali e rendere più frequenti le missioni a lungo raggio."
   ],
