   "id": "zcbd8ff7e",
   "sez": "mondo",
   "titolo": "Attacco di drone ucraino incendia una raffineria russa a Volgograd",
   "orig": "Volgograd oil refinery, Rostov-on-Don production facility in flames following Ukrainian drone attack",
   "lead": "Un attacco con drone ucraino ha provocato un incendio alla raffineria Lukoil-Volgogradneftepererabotka a Volgograd, uno dei maggiori impianti di raffinazione petrolifera della Russia con una capacità annua di 15 milioni di tonnellate di petrolio grezzo. Testimoni oculari hanno filmato le fiamme che si levavano dall'impianto. Un'altra struttura produttiva a Rostov-on-Don risulta parimenti colpita dalle fiamme. Lo riferisce The Kyiv Independent.",
   "more": [
    "Le raffinerie petrolifere russe sono state ripetutamente colpite da attacchi con drone ucraini nel corso del conflitto, con l'obiettivo di colpire le entrate energetiche di Mosca, che finanziano in parte lo sforzo militare russo. La raffineria di Volgograd è uno dei maggiori impianti del paese per capacità di lavorazione del greggio."
   ],
