   "id": "z0351149d",
   "sez": "salute",
   "titolo": "Kenya avvia il conto alla rovescia per la fine dell'epidemia di Ebola",
   "orig": "Kenya begins countdown towards end of Ebola after last patient discharged",
   "lead": "Il Kenya ha iniziato giovedì un periodo di osservazione di 42 giorni che porterà alla possibile dichiarazione di fine dell'epidemia di Ebola, un giorno dopo che l'ultimo paziente in cura per la malattia è stato dimesso e 11 persone sono state liberate dalla quarantena. Nel frattempo, a Goma, l'organizzazione Medici Senza Frontiere chiede maggiore efficacia e trasparenza nella risposta all'epidemia nella Repubblica Democratica del Congo, nonostante i fondi mobilitati, mentre l'UNICEF ha elogiato i progressi compiuti a Bunia. Lo riferiscono UN News e Radio Okapi.",
   "more": [
    "L'Ebola è una malattia virale emorragica con alta letalità, trasmessa tramite contatto con fluidi corporei di persone infette. Le epidemie vengono dichiarate concluse dopo un periodo di sorveglianza, generalmente di 42 giorni (il doppio del periodo di incubazione massimo), senza nuovi casi confermati, per garantire che il virus non circoli più nella popolazione."
   ],
