   "id": "z8ff6b8e6",
   "sez": "dibattito",
   "titolo": "Praga si prepara alla grande manifestazione di Letná di domenica",
   "orig": "Prague Adds Special Trams and More Metro Services for Letná Demonstration",
   "lead": "Praga ha organizzato tram e servizi metro straordinari per domenica 15 novembre, in occasione di una grande manifestazione prevista nella zona di Letná. La protesta, organizzata dal movimento Million Moments for Democracy (Milion chvilek), dovrebbe attirare migliaia di persone da tutto il paese. Le fonti non specificano le richieste dei manifestanti. La città aumenterà la frequenza dei treni sulle tre linee della metropolitana e introdurrà due nuove linee tram temporanee per facilitare gli spostamenti verso il luogo della protesta. Lo riferiscono Prague Morning e Expats.cz.",
   "more": [
    "Million Moments for Democracy è un movimento civico ceco nato nel 2017, noto per aver organizzato grandi manifestazioni contro il governo, in particolare sotto la guida dell'ex premier Andrej Babiš, accusato di conflitti di interesse. Le manifestazioni a Letná, grande parco nel centro di Praga, sono tradizionalmente tra le più numerose del paese."
   ],
