   "titolo": "Un viaggio nella cultura pop lungo la Route 66, che compie 100 anni",
   "orig": "Hop in: We're taking a pop culture road trip on Route 66",
   "lead": "La Route 66, la storica autostrada statunitense che attraversa otto stati, festeggia 100 anni dalla sua creazione. L'iconica strada, comparsa per decenni in film, libri, musica e arte, è protagonista di un viaggio attraverso la cultura popolare americana che ne racconta l'eredità. Lo riferisce NPR.",
