   "orig": "Igd, in 9 mesi salgono utili e ricavi da affitti. Si alza anche la guidance e l’outlook è positivo",
   "lead": "La società immobiliare Igd ha chiuso i primi nove mesi dell'anno con un aumento di utili e ricavi derivanti dagli affitti dei suoi centri commerciali. I ricavi netti da canoni sulle proprietà si attestano a 75,9 milioni di euro, in crescita del 3,4% a parità di perimetro, mentre l'ebitda della gestione caratteristica raggiunge 72,4 milioni. L'azienda ha inoltre innalzato le previsioni per l'anno in corso, segnalando un outlook positivo, e registra un allungamento della durata media residua dei contratti di locazione. Lo riferisce Il Sole 24 Ore.",
