   "titolo": "Cunningham segna 52 punti, i Pistons battono i Wizards ai doppi tempi supplementari",
   "orig": "NBA: Cunningham scores 52 as Pistons win double OT thriller against Wizards",
   "lead": "La guardia dei Detroit Pistons Cade Cunningham ha segnato 52 punti nella vittoria 144-140 ai doppi tempi supplementari contro i Washington Wizards. Cunningham è diventato il primo giocatore NBA a registrare una partita da 50 punti e 10 assist senza alcuna palla persa dal 1977-78. La prestazione si inserisce in una stagione in cui il giocatore sta emergendo come uno dei protagonisti della lega. Lo riferisce Al Jazeera.",
