   "id": "z69e32d23",
   "sez": "salute",
   "titolo": "L'Agenzia europea per i medicinali raccomanda sette nuovi farmaci",
   "orig": "Meeting highlights from the Committee for Medicinal Products for Human Use (CHMP) 9-12 November 2026",
   "lead": "Il comitato per i medicinali per uso umano (CHMP) dell'Agenzia europea per i medicinali (Ema) ha raccomandato l'approvazione di sette nuovi farmaci durante la riunione di novembre 2026, svolta tra il 9 e il 12 novembre. Tra i prodotti valutati positivamente figura Aumseqa, a base del principio attivo aumolertinib, presentato dall'azienda SFL Pharmaceuticals. Le raccomandazioni del comitato rappresentano un passaggio necessario prima dell'autorizzazione definitiva all'immissione in commercio nell'Unione europea. Lo riferisce l'Agenzia europea per i medicinali.",
   "more": [
    "Il CHMP valuta periodicamente domande di autorizzazione per nuovi farmaci nell'Unione europea. Una raccomandazione positiva del comitato viene poi trasmessa alla Commissione europea, che formalizza l'autorizzazione alla commercializzazione in tutti gli Stati membri, passaggio che generalmente richiede alcune settimane dopo il parere scientifico."
   ],
