   "id": "zcb15d405",
   "sez": "salute",
   "titolo": "In Afghanistan le donne hanno sempre più difficoltà ad accedere alle cure medi che",
   "orig": "Afghanistan, sempre più difficili le cure mediche per le donne",
   "lead": "Un'inchiesta condotta da The Guardian e Zan Times documenta come le restrizioni imposte dalle autorità talebane di Kabul stiano rendendo sempre più difficile per le donne afghane l'accesso alle cure sanitarie. L'indagine raccoglie testimonianze di pazienti respinte dalle cliniche e di medici che denunciano minacce di arresto per aver curato donne. La situazione aggrava le condizioni di salute femminile nel paese, già colpito da altre restrizioni sociali imposte dal governo. Lo riferisce Vatican News.",
   "more": [
    "Dal ritorno al potere dei talebani in Afghanistan nel 2021, le donne hanno subito progressive restrizioni nell'accesso a istruzione, lavoro e spazi pubblici. Diverse organizzazioni internazionali hanno denunciato un peggioramento delle condizioni sanitarie femminili, legato anche alla limitazione del personale medico donna disponibile per curare le pazienti."
   ],
