   "lead": "Il governo di Hong Kong ha innalzato venerdì le previsioni di crescita del Pil per il 2026 al 4,8%, rispetto alla precedente stima tra il 3,5% e il 4,5%. La revisione segue una forte espansione economica registrata nel terzo trimestre, con una crescita del 5,2% su base annua, superiore al 4,2% del trimestre precedente. L'economista governativo Irina Fan ha dichiarato attesa di una crescita solida anche negli ultimi tre mesi dell'anno. Lo riferisce RTHK.",
