   "titolo": "Settimo giorno del viaggio di Papa Leone XIV in Perù",
   "orig": "In un minuto la settima giornata di Leone XIV in America Latina",
   "lead": "Papa Leone XIV ha trascorso il settimo giorno del suo viaggio apostolico in America Latina proseguendo le tappe in Perù, nell'ambito di un itinerario che include tre paesi sudamericani. Vatican Media ha diffuso immagini esclusive degli appuntamenti del pontefice nella giornata. Lo riferisce Vatican News.",
   "more": [
    "I viaggi apostolici dei pontefici in America Latina hanno storicamente un forte valore simbolico, data la grande presenza cattolica nella regione. Le visite comprendono tipicamente incontri con autorità locali, celebrazioni liturgiche pubbliche e momenti dedicati a comunità povere o emarginate."
   ],
