   "id": "zccc0f52f",
   "sez": "mondo",
   "titolo": "Gli Stati Uniti permettono ai messicani di entrare senza passaporto con la tessera DSP-150",
   "orig": "Oficial | Estados Unidos permite a mexicanos ingresar sin pasaporte con la tarjeta DSP-150: requisitos y límites en cuatro estados",
   "lead": "Gli Stati Uniti consentono ai cittadini messicani di entrare nel paese senza passaporto utilizzando la tessera DSP-150, nota come Tarjeta de Cruce Fronterizo, che funziona come un visto di visitatore B1/B2 e permette l'ingresso via terra dal Messico. Il beneficio è limitato a specifiche zone di Texas, California, Arizona e Nuovo Messico, con una permanenza massima di 30 giorni senza necessità del modulo I-94. Lo riferisce Clarín.",
   "more": [
    "La Tarjeta de Cruce Fronterizo è un documento usato da decenni per facilitare gli spostamenti transfrontalieri tra Messico e Stati Uniti, soprattutto per motivi di lavoro, turismo o visite familiari in aree di confine, dove il traffico quotidiano tra i due paesi è molto intenso."
   ],
