   "id": "z232cb434",
   "sez": "mondo",
   "titolo": "Esplosione di un'auto a Mosca ferisce un ex consigliere ucraino",
   "orig": "A car exploded in Moscow. Telegram channels say it belongs to Sergei Zavorotny, former spokesman for Ukrainian ex-prime minister Mykola Azarov.",
   "lead": "Un'auto Toyota è esplosa nel distretto moscovita di Chertanovo, secondo quanto riportato da canali Telegram russi e confermato dal Comitato investigativo russo. A bordo si trovava Sergei Zavorotny, 72 anni, ex portavoce dell'ex primo ministro ucraino Mykola Azarov, trasferitosi in Russia dopo la rivoluzione di Maidan del 2014. L'uomo è rimasto ferito e trasportato in ospedale per cure. Non sono ancora chiare le cause dell'esplosione. Lo riferisce Meduza, con conferme da TASS e Moscow Times.",
   "more": [
    "Mykola Azarov è stato primo ministro dell'Ucraina sotto la presidenza di Viktor Yanukovich, rovesciato dalla Rivoluzione di Euromaidan nel 2014. Diversi membri del suo entourage si sono poi trasferiti in Russia, dove da anni si registrano episodi violenti e misteriosi contro figure legate all'ex governo ucraino filorusso."
   ],
