   "id": "zb645d494",
   "sez": "mondo",
   "titolo": "La Turchia nega piani per inviare 15mila soldati in Somalia",
   "orig": "Turkish Defense Ministry denies plans to send 15,000 troops to Somalia",
   "lead": "Il ministero della Difesa turco ha smentito giovedì le indiscrezioni secondo cui Ankara prevederebbe di inviare 15mila soldati in Somalia su richiesta del governo somalo. Secondo l'agenzia Anka, la Turchia ha precisato che le proprie forze già presenti nel paese continueranno a fornire assistenza militare, addestramento e consulenza, senza alcun piano di incremento nella misura riportata dalle voci circolate. Lo riferisce Turkish Minute, con conferme da Hiiraan Online e Somali Guardian.",
   "more": [
    "La Turchia mantiene da anni una delle proprie basi militari più grandi all'estero in Somalia, dove fornisce addestramento alle forze armate somale nel contesto della lotta al gruppo armato al-Shabaab e del processo di transizione della sicurezza nel paese."
   ],
