   "id": "z6ae68e1d",
   "sez": "cultura",
   "titolo": "Lo scrittore Giuliano da Empoli avverte sui rischi della dittatura algoritmica",
   "orig": "« L’IA va faire de nous tous des figurants » : l’avertissement de l’écrivain prophète Giuliano da Empoli contre la dictature des algorithmes",
   "lead": "Lo scrittore italiano Giuliano da Empoli, autore de 'Il Mago del Cremlino', presenta il suo nuovo romanzo 'Il Fondatore', ambientato nel mondo dei signori della tecnologia. Secondo l'autore, intervistato da Le Figaro, l'intelligenza artificiale rischia di trasformare tutti in semplici comparse, in un mondo sempre più governato dagli algoritmi. L'opera, descritta come una distopia, si basa secondo l'autore su elementi quasi interamente veri.",
   "more": [
    "Giuliano da Empoli è uno scrittore e politologo italiano noto per i suoi romanzi che esplorano i rapporti tra potere politico, tecnologia e comunicazione contemporanea. Il tema del potere delle grandi aziende tecnologiche e dell'intelligenza artificiale è oggetto di crescente dibattito pubblico in Europa e nel mondo."
   ],
