   "id": "z987d0043",
   "sez": "prima",
   "titolo": "Un tribunale britannico condanna due iraniani per spionaggio su giornalisti",
   "orig": "UK court convicts 2 Iranian men of spying on journalists",
   "lead": "Un tribunale di Londra ha condannato due cittadini iraniani per aver sorvegliato giornalisti di un'emittente televisiva in lingua persiana critica verso il governo iraniano. Uno dei due è stato condannato anche per aver pianificato un attacco violento contro i giornalisti presi di mira. La polizia britannica ha definito la condanna la prima del suo genere secondo una legge introdotta nel 2023 per contrastare le minacce provenienti da stati stranieri, in aumento negli ultimi anni. Lo riferisce Deutsche Welle, con conferma da Haaretz.",
   "more": [
    "La legge britannica sulla sicurezza nazionale del 2023 ha introdotto nuovi reati per contrastare le attività di spionaggio e intimidazione condotte da stati stranieri sul territorio del Regno Unito, in risposta a un aumento di casi legati a regimi autoritari che perseguono dissidenti e giornalisti all'estero."
   ],
