     "t": "Articolo investigativo che documenta il passaggio del Kennedy Center a Ticketmaster e il possibile conflitto di interessi dell'ex presidente Richard Grenell, pagato come membro del board di Live Nation (260.205 dollari nel 2025) mentre negoziava l'accordo. Cita l'esperto di etica Richard Briffault, che parla di \"letteralmente conflitto di interesse\", e riporta le smentite del Kennedy Center e di Ticketmaster.",
