     "t": "La voce dell'Irlanda focalizza il resoconto sulle indagini di polizia e sul no del giudice all'ingiunzione richiesta da Walliams. Elenca le ripercussioni professionali e politiche, tra cui la sospensione dal Labour e la rimozione dei suoi show dalla BBC. L'impostazione è puramente informativa.",
