     "t": "La voce del Canada evidenzia le accuse di condotte illegali su quindicenni e le conseguenze sul film \"Fing!\". Mette in risalto il confronto con la condanna del comico Russell Brand e il dibattito pubblico nel Paese. Il resoconto è informativo e dettagliato.",
