     "t": "Fornisce una ricostruzione fattuale dell'inchiesta di polizia a carico di Walliams, citando la lettera inviata ai reporter in cui ammette comportamenti \"senza considerazione\" ma nega violazioni di legge. Ricostruisce i suoi trascorsi televisivi ed editoriali. L'articolo è puramente informativo e neutro.",
