     "n": "Rai News",
     "c": "Roma",
     "p": "IT",
     "t": "Giudizio parziale: solo titolo e occhiello disponibili. Riporta che Kallas rivendica il proprio ruolo di rappresentante Ue, criticando l'idea di nominare \"una persona senza alcun ruolo\".",
